			// Indexing is always local-only and always targets committed HEAD.
		case "--worktree":
			return flags, nil, errors.New("index is HEAD-only; --worktree is not supported")
		default:
			rest = append(rest, args[index])
		}
	}
	return flags, rest, nil
}

